// Check that the generated deployment pins still describe the checked-in manifests and the public CHAINS.
//
// The generator itself proves that the generated bytes are current. This guard proves the next step: every live pin
// is actually the one the SDK exposes, and an unknown network never silently falls back to another chain.
import { execFileSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  CHAINS,
  DEPLOYMENTS,
  DEPLOYMENT_CHAINS,
  FACTORY_HISTORY,
  KNOWN_FACTORY_CODES,
  deploymentFor,
} from "../engine/core/config.js";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const problems = [];

function check(condition, message) {
  if (!condition) problems.push(message);
}

function sameEscrow(chainEscrow, pinEscrow) {
  if (!chainEscrow || !pinEscrow) return false;
  return chainEscrow.address === pinEscrow.address
    && chainEscrow.mode === pinEscrow.mode
    && chainEscrow.cashier === pinEscrow.cashier
    && chainEscrow.registry === pinEscrow.registry
    && chainEscrow.deploymentBlock === pinEscrow.deploymentBlock
    && chainEscrow.implementationCodeHash === pinEscrow.implementationCodeHash;
}

// 1. The generated module is current.
try {
  execFileSync(process.execPath, [join(ROOT, "tools", "gen-deployment-pins.mjs"), "--check"], {
    cwd: ROOT,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
} catch (error) {
  const text = String((error && (error.stdout || error.stderr || error.message)) || error);
  problems.push(`generated pins are stale: ${text.trim() || "gen-deployment-pins --check failed"}`);
}

// 2. Each live pin is exported under its own network, by both its id and its CAIP-2, and never by a numeric guess
// that points at another network.
for (const [network, pin] of Object.entries(DEPLOYMENTS)) {
  check(pin.network === network, `${network}: pin.network is ${pin.network}`);
  check(DEPLOYMENT_CHAINS.includes(network), `${network}: absent from DEPLOYMENT_CHAINS`);
  check(deploymentFor(network) === pin, `${network}: deploymentFor(id) did not return the pin`);
  check(deploymentFor(pin.caip2) === pin, `${network}: deploymentFor(caip2) did not return the pin`);
  check(deploymentFor(Number(pin.chainRef)) === pin, `${network}: deploymentFor(chain id) did not return the pin`);
  check(deploymentFor("eip155:999999") === null, `${network}: an unknown CAIP-2 returned a pin`);

  if (pin.status !== "live") continue;
  const chain = CHAINS.find((entry) => entry.id === network);
  if (!chain) {
    problems.push(`${network}: live pin has no CHAINS entry`);
    continue;
  }
  check(sameEscrow(chain.escrow, pin.escrow), `${network}: CHAINS escrow differs from the generated pin`);
  check(JSON.stringify(KNOWN_FACTORY_CODES[network]) === JSON.stringify([...pin.knownFactoryCodes]),
    `${network}: KNOWN_FACTORY_CODES differs from the factory code hash`);
  check(chain.vm === "evm" && pin.vm === "evm", `${network}: a live pin is not the EVM shape this guard checks`);
}

// 3. The factory history contains the current factory exactly once, keeps old factories ordered by block, and
// never mixes a live factory into the retired list.
for (const [network, pin] of Object.entries(DEPLOYMENTS)) {
  const history = FACTORY_HISTORY[network];
  check(Array.isArray(history) && history.length > 0, `${network}: FACTORY_HISTORY is missing`);
  if (!Array.isArray(history)) continue;
  const addresses = history.map((entry) => String(entry.address).toLowerCase());
  check(new Set(addresses).size === addresses.length, `${network}: FACTORY_HISTORY repeats an address`);
  const live = history.filter((entry) => entry.status === "live");
  check(live.length === 1, `${network}: FACTORY_HISTORY has ${live.length} live factories, expected one`);
  if (live.length === 1) {
    check(live[0].address.toLowerCase() === pin.escrow.address.toLowerCase(),
      `${network}: the live history entry is not the current factory`);
    check(live[0].deploymentBlock === pin.escrow.deploymentBlock,
      `${network}: the live history block is not the pin block`);
  }
  const blocks = history.map((entry) => Number(entry.deploymentBlock));
  check(blocks.every((block) => Number.isSafeInteger(block) && block > 0), `${network}: a history entry has no block`);
  check(blocks.every((block, i) => i === 0 || block >= blocks[i - 1]), `${network}: history is not ordered by block`);
  check(history.filter((entry) => entry.status === "retired").every((entry) => Boolean(entry.release && entry.release.tag)),
    `${network}: a retired history entry has no release tag`);
}
for (const network of Object.keys(FACTORY_HISTORY)) {
  check(Boolean(DEPLOYMENTS[network]), `${network}: FACTORY_HISTORY has no deployment pin`);
}

console.log(problems.length ? `FAILED: ${problems.length}` : `deployment pins: ${Object.keys(DEPLOYMENTS).length} networks current`);
if (!problems.length) {
  const historyCount = Object.values(FACTORY_HISTORY).reduce((sum, list) => sum + list.length, 0);
  console.log(`  ok    ${Object.keys(DEPLOYMENTS).length} live pins and ${historyCount} factory history entries are current`);
}
for (const problem of problems) console.log(`  FAIL  ${problem}`);
process.exit(problems.length ? 1 : 0);
